window.kbPageData["views/entry/k-e37f814fbdab8427"] = {"key":"entry/k-e37f814fbdab8427","state":{"route":"entry/k-e37f814fbdab8427"},"node":{"id":"k-e37f814fbdab8427","mode":"k","title":"网络购物七日无理由退货的例外","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["网络销售不得擅自扩大无理由退货例外且须提示消费者确认"],"qs":["国考 2025 地市级 行测#25"],"current":true,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"网络购物原则上适用自收到商品之日起七日内无理由退货。除法律直接列明的例外外，经营者主张某商品依其性质不宜退货的，应当显著标注并由消费者在购买时确认，不得擅自扩大例外范围或设置默认同意。","review":{"definition":"网络购物原则上适用自收到商品之日起七日内无理由退货。除法律直接列明的例外外，经营者主张某商品依其性质不宜退货的，应当显著标注并由消费者在购买时确认，不得擅自扩大例外范围或设置默认同意。","explanation":"C项的直播卖衣服属于网络销售。主播称服装是尾货或瑕疵品，并提醒谨慎购买，既不足以认定这批服装依其性质不宜退货，也没有体现消费者在购买时作出确认，因此不能据此排除七日无理由退货。","references":[],"evidence":"不得将不适用无理由退货作为消费者默认同意的选项。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 地市级 行测#25":{"paper":"国考 2025 地市级 行测","n":25,"mod":"常识判断","src":["31f401e91aef8d11365d.pdf",4],"asrc":["8cece062c7c079b53130.pdf",9],"card":"9a08f2919c7392c6c4b12c24","links":[{"id":"k-e37f814fbdab8427","role":"解题依据","why":"直播中提示尾货或瑕疵，仍须核对商品是否属于适用例外的范围以及消费者是否在购买时确认。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-e37f814fbdab8427":[["国考 2025 地市级 行测#25"]]}};
